import type { PlatformId } from './games';

/** Box-art faces generated by `npm run covers` (see scripts/covers.mjs), keyed by game id. */
export interface Cover {
  front: string;
  spine?: string;
  back?: string;
}

const files = import.meta.glob<string>('../assets/covers/*.webp', { eager: true, query: '?url', import: 'default' });

export const covers = new Map<string, Cover>();
for (const [file, url] of Object.entries(files)) {
  // "<id>-<face>.<hash>.webp": the hash changes with the image, so a swapped cover never comes from cache.
  const m = file.match(/\/([^/]+)-(front|spine|back)(?:\.[0-9a-f]+)?\.webp$/);
  if (!m) continue;
  const [, id, face] = m;
  covers.set(id, { ...covers.get(id), [face]: url } as Cover);
}

/** Physical case proportions per console (front width and spine depth, relative to height). */
export interface CaseSpec {
  aspect: number;
  depth: number;
  /** Plastic colour, seen on the edges and on the banner of blank cases. */
  plastic: string;
  /** Text colour on top of the plastic colour. */
  plasticInk: string;
  /** Height relative to the shelf's base case height (3DS cases are short and wide). */
  scale: number;
}

export const caseSpecs: Record<PlatformId, CaseSpec> = {
  switch: { aspect: 0.62, depth: 0.065, plastic: '#D7192A', plasticInk: '#FFFFFF', scale: 1 },
  '3ds': { aspect: 1.12, depth: 0.1, plastic: '#EEF1F4', plasticInk: '#1E293B', scale: 0.74 },
  ds: { aspect: 0.88, depth: 0.1, plastic: '#E6EBF0', plasticInk: '#1E293B', scale: 0.82 },
  wii: { aspect: 0.71, depth: 0.075, plastic: '#F5F7F9', plasticInk: '#1E293B', scale: 1.06 },
  ps4: { aspect: 0.79, depth: 0.085, plastic: '#2050A8', plasticInk: '#FFFFFF', scale: 1 },
};
